using Content.Shared.Humanoid.Prototypes;
using Robust.Shared.Prototypes;

namespace Content.Shared._WF.Augments;

/// <summary>
/// A limb outline some bodies draw that differs from the human's, with the base sprites that draw it. Styles carry a
/// version of each limb fitted to it (<see cref="WFAugmentStylePrototype.Fitted"/>). Generated by the port script.
/// </summary>
[Prototype("wfAugmentShape")]
public sealed partial class WFAugmentShapePrototype : IPrototype
{
    [IdDataField]
    public string ID { get; private set; } = default!;

    [DataField(required: true)]
    public List<ProtoId<HumanoidSpeciesSpriteLayer>> BaseSprites = new();
}
